#include <iostream>

int main() {
    int i = 3;
    int j = 5;

    // Incorrect cast placement: i / j evaluates to 0 first
    double bad_result = static_cast<double>(i / j) * 10.0;

    // Correct cast placement: promotes operand to double before division
    double good_result = static_cast<double>(i) / j * 10.0;

    char ch = 'A';
    int ascii_val = static_cast<int>(ch);

    std::cout << "Bad: " << bad_result << "\n";
    std::cout << "Good: " << good_result << "\n";
    std::cout << "ASCII: " << ascii_val << "\n";

    return 0;
}

#include <iostream>

int main() {
    int val = 10; // Outer variable

    {
        // Inner block
        int val = 50; // Shadows outer 'val'
        int temp = 5;
        std::cout << "Inner val: " << val << ", temp: " << temp << "\n";
    }

    // 'temp' is destroyed here and cannot be accessed
    std::cout << "Outer val: " << val << "\n";

    return 0;
}

#include <iostream>
#include <cmath>
#include <iomanip>

int main() {
    // Nested square root: sqrt(3 + sqrt(3 + sqrt(3)))
    double nested_sqrt = std::sqrt(3.0 + std::sqrt(3.0 + std::sqrt(3.0)));

    // Continued fraction: 1 / (2 + 1 / (2 + 1 / 2.0))
    double cont_fraction = 1.0 / (2.0 + 1.0 / (2.0 + 1.0 / 2.0));

    // Perfect square test using sqrt
    int n = 16;
    double root = std::sqrt(n);
    bool is_square = (static_cast<int>(root) * static_cast<int>(root) == n);

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "Nested sqrt: " << nested_sqrt << "\n";
    std::cout << "Continued fraction: " << cont_fraction << "\n";
    std::cout << "Is " << n << " square: " << (is_square ? "true" : "false") << "\n";

    return 0;
}
